export function prorateMonthlyCharge(monthlyCents: number, daysUsed: number, daysInMonth: number) {
    if (daysInMonth <= 0 || daysUsed < 0 || daysUsed > daysInMonth)
        throw new Error('Invalid billing days');
    return Math.round(monthlyCents * daysUsed / daysInMonth);
}
